// This is the complete credential-free nft 1.1.3 listing from installed run
// 41011045734, not a graph generated by the compiler under test. Its original
// named underlay operand did not expose the index; the pure test supplies an
// explicit controlled current-link map with underlay index 3.
func nativeNFTObservedShapeFixture(t *testing.T) (smartTUNTrialJournal, []map[string]any, map[string]int) {
	t.Helper()
	raw, err := os.ReadFile(filepath.Join("testdata", "native-nft-ipv4-1.1.3.json"))
	if err != nil {
		t.Fatal(err)
	}
	if sha256Hex(raw) != "3ca2d131ebbff32d656386e89cdb63a6a2dced08778885abd8b797f913d67e79" {
		t.Fatal("native nft evidence fixture changed")
	}
	r := nativeTrialExample(true)
	r.OperationID = "5f4c8ceaf238be74151d0ca235c6a7dc"
	r.Native.NFTName = "scnt_" + r.OperationID
	r.Native.LinkIndex = 22
	r.Native.IPv6 = nativeTUNPlannedFamily("", nativeTUNTable6)
	r.Native.IPv6.DependentSHA256 = strings.Repeat("c", 64)
	objects, err := nativeTUNNftObjects(raw)
	if err != nil {
		t.Fatal(err)
	}
	rows, err := selectiveRows(json.RawMessage(`[{"ifindex":1,"ifname":"lo"},{"ifindex":3,"ifname":"scqaedge0"},{"ifindex":22,"ifname":"sctunqa0","ifalias":"server-connect:` + r.OperationID + `"}]`))
	if err != nil {
		t.Fatal(err)
	}
	indices, err := nativeNFTInterfaceMap(rows, r)
	if err != nil {
		t.Fatal(err)
	}
	return r, objects, indices
}

func nativeNFTObserveShapeFixture(t *testing.T, r smartTUNTrialJournal, objects []map[string]any, indices map[string]int) nativeTUNNFTObservation {
	t.Helper()
	if err := nativeNFTPinInterfaces(objects, indices); err != nil {
		t.Fatal(err)
	}
	observed, err := nativeTUNNFTFromRows(objects, r, 71)
	if err != nil {
		t.Fatal(err)
	}
	return observed
}

func TestSmartTUNNativeNFTMatchesActualPinnedListing(t *testing.T) {
	r, objects, indices := nativeNFTObservedShapeFixture(t)
	observed := nativeNFTObserveShapeFixture(t, r, objects, indices)
	if !observed.Matches || observed.Count != 22 {
		wanted := nativeNFTObjects(r)
		for i := range objects {
			if i >= len(wanted) {
				break
			}
			a, _ := nativeNFTObjectHash([]map[string]any{objects[i]}, true)
			b, _ := nativeNFTObjectHash([]map[string]any{wanted[i]}, true)
			if a != b {
				t.Logf("native object %d differs: observed=%v expected=%v", i, objects[i], wanted[i])
			}
		}
		t.Fatalf("actual native graph not recognized: matches=%v count=%d", observed.Matches, observed.Count)
	}
	bindNativeNFTReceipt(&r, observed)
	if err := validateSmartTUNNative(r); err != nil {
		t.Fatalf("actual receipt is not bound to intended manifest: %v", err)
	}
	if !nativeTUNNFTReceiptCovers(r, observed, true) || !nativeTUNGuardIntact(r, observed) {
		t.Fatal("actual complete ownership/guard receipt rejected")
	}

	// The same unchanged rule becomes an exact decimal string when the TUN
	// is removed. Preserve its original index and handles in the receipt.
	_, after, remaining := nativeNFTObservedShapeFixture(t)
	delete(remaining, r.TunnelInterface)
	r.Native.LinkStage = "removed"
	for _, object := range after {
		rule, ok := object["rule"].(map[string]any)
		if !ok {
			continue
		}
		for _, expr := range rule["expr"].([]any) {
			match, ok := expr.(map[string]any)["match"].(map[string]any)
			if ok && match["right"] == r.TunnelInterface {
				match["right"] = strconv.Itoa(r.Native.LinkIndex)
			}
		}
	}
	afterObserved := nativeNFTObserveShapeFixture(t, r, after, remaining)
	if !afterObserved.Matches || afterObserved.SHA256 != observed.SHA256 || !nativeTUNNFTReceiptCovers(r, afterObserved, true) {
		t.Fatal("deleted-link decimal rendering changed exact nft ownership")
	}
}

func TestSmartTUNNativeNFTActualShapeRejectsPolicyAndOrderChanges(t *testing.T) {
	original, objects, indices := nativeNFTObservedShapeFixture(t)
	baseline := nativeNFTObserveShapeFixture(t, original, objects, indices)
	if !baseline.Matches {
		t.Fatal("actual fixture must match before negative checks")
	}
	bindNativeNFTReceipt(&original, baseline)
	rule := func(objects []map[string]any, index int) map[string]any {
		return objects[index]["rule"].(map[string]any)
	}
	exprs := func(objects []map[string]any, index int) []any { return rule(objects, index)["expr"].([]any) }
	for _, tc := range []struct {
		name   string
		change func([]map[string]any)
	}{
		{"chain header order", func(o []map[string]any) { o[1], o[2] = o[2], o[1] }},
		{"rule order with original handles", func(o []map[string]any) { o[12], o[13] = o[13], o[12] }},
		{"expression order", func(o []map[string]any) { e := exprs(o, 18); e[0], e[1] = e[1], e[0] }},
		{"drop changed to accept", func(o []map[string]any) { exprs(o, 21)[1] = map[string]any{"accept": nil} }},
		{"public destination exemption", func(o []map[string]any) {
			m := exprs(o, 15)[0].(map[string]any)["match"].(map[string]any)
			m["right"].(map[string]any)["set"].([]any)[0].(map[string]any)["prefix"].(map[string]any)["len"] = json.Number("0")
		}},
		{"reply selector inverted", func(o []map[string]any) {
			exprs(o, 13)[0].(map[string]any)["match"].(map[string]any)["right"] = json.Number("0")
		}},
		{"underlay accepted as TUN", func(o []map[string]any) {
			exprs(o, 20)[2].(map[string]any)["match"].(map[string]any)["right"] = json.Number("3")
		}},
		{"mark loses foreign low bit", func(o []map[string]any) {
			m := exprs(o, 11)[2].(map[string]any)["mangle"].(map[string]any)
			m["value"].(map[string]any)["|"].([]any)[0].(map[string]any)["&"].([]any)[1] = json.Number("4283695102")
		}},
		{"capture becomes bypass mark", func(o []map[string]any) {
			m := exprs(o, 11)[2].(map[string]any)["mangle"].(map[string]any)
			m["value"].(map[string]any)["|"].([]any)[1] = json.Number("5505024")
		}},
		{"unknown rule field", func(o []map[string]any) { rule(o, 12)["future_effect"] = true }},
		{"unknown expression retained", func(o []map[string]any) {
			r := rule(o, 12)
			r["expr"] = append(exprs(o, 12), map[string]any{"future_effect": true})
		}},
	} {
		t.Run(tc.name, func(t *testing.T) {
			r, current, mapping := nativeNFTObservedShapeFixture(t)
			if err := nativeNFTPinInterfaces(current, mapping); err != nil {
				t.Fatal(err)
			}
			tc.change(current)
			observed, err := nativeTUNNFTFromRows(current, r, 72)
			if err == nil && (observed.Matches || nativeTUNNFTReceiptCovers(original, observed, false)) {
				t.Fatal("altered policy/order was normalized into intended ownership")
			}
		})
	}
	// Handles are stripped for intended semantic comparison only. A replaced
	// handle must still fail the durable ownership receipt, independently.
	r, current, mapping := nativeNFTObservedShapeFixture(t)
	if err := nativeNFTPinInterfaces(current, mapping); err != nil {
		t.Fatal(err)
	}
	rule(current, 12)["handle"] = json.Number("9000")
	replaced, err := nativeTUNNFTFromRows(current, r, 73)
	if err != nil || !replaced.Matches || nativeTUNNFTReceiptCovers(original, replaced, false) {
		t.Fatal("same-policy handle replacement escaped exact receipt")
	}
}

func TestSmartTUNNativeNFTInterfaceMappingMustRemainCurrent(t *testing.T) {
	r, _, indices := nativeNFTObservedShapeFixture(t)
	base := `[{"ifindex":1,"ifname":"lo"},{"ifindex":3,"ifname":"scqaedge0"},{"ifindex":22,"ifname":"sctunqa0","ifalias":"server-connect:` + r.OperationID + `"}]`
	for _, raw := range []string{
		strings.Replace(base, `"ifindex":3`, `"ifindex":4`, 1),
		strings.Replace(base, `"ifindex":22`, `"ifindex":23`, 1),
		strings.Replace(base, `"ifname":"sctunqa0"`, `"ifname":"replacement0"`, 1),
		strings.Replace(base, r.OperationID, strings.Repeat("a", 32), 1),
		strings.Replace(base, `"ifindex":22`, `"ifindex":3`, 1),
	} {
		rows, err := selectiveRows(json.RawMessage(raw))
		if err != nil {
			t.Fatal(err)
		}
		if _, err := nativeNFTInterfaceMap(rows, r); ErrorCode(err) != "trial_resource_conflict" {
			t.Fatal("changed/duplicate current identity accepted for nft name resolution")
		}
	}
	rows, _ := selectiveRows(json.RawMessage(base))
	removed := cloneSmartTUNTrial(r)
	removed.Native.LinkStage = "removed"
	if _, err := nativeNFTInterfaceMap(rows, removed); ErrorCode(err) != "trial_resource_conflict" {
		t.Fatal("reappeared TUN became current nft identity")
	}
	withoutTUN, _ := selectiveRows(json.RawMessage(`[{"ifindex":1,"ifname":"lo"},{"ifindex":3,"ifname":"scqaedge0"}]`))
	if _, err := nativeNFTInterfaceMap(withoutTUN, removed); err != nil {
		t.Fatal("actual owned-link absence must remain observable")
	}
	changed := map[string]int{}
	for name, index := range indices {
		changed[name] = index
	}
	if !nativeNFTSameInterfaces(indices, changed) {
		t.Fatal("equal complete interface snapshots rejected")
	}
	changed["foreign0"] = 30
	if nativeNFTSameInterfaces(indices, changed) {
		t.Fatal("new disjoint link cannot be hidden between observation snapshots")
	}
	delete(changed, "foreign0")
	changed[r.TunnelInterface] = 23
	if nativeNFTSameInterfaces(indices, changed) {
		t.Fatal("changed mapping passed snapshot equality")
	}
}

func TestSmartTUNNativeNFTNormalizesOnlyTypedInterfaceOperands(t *testing.T) {
	r, _, indices := nativeNFTObservedShapeFixture(t)
	for _, tc := range []struct {
		raw      string
		conflict bool
	}{
		{`{"match":{"op":"==","left":"scqaedge0","right":{"meta":{"key":"iif"}}}}`, false},
		{`{"match":{"op":"==","left":{"meta":{"key":"oif"}},"right":{"set":["lo","scqaedge0"]}}}`, false},
		{`{"match":{"op":"==","left":{"meta":{"key":"oif"}},"right":{"set":["lo","sctunqa0"]}}}`, true},
	} {
		var value any
		dec := json.NewDecoder(strings.NewReader(tc.raw))
		dec.UseNumber()
		if err := dec.Decode(&value); err != nil {
			t.Fatal(err)
		}
		if err := nativeNFTPinInterfaceMatches(value, indices); err != nil {
			t.Fatal(err)
		}
		if got := nativeNFTForeignConflict(value, r); got != tc.conflict {
			t.Fatalf("typed foreign interface dependency lost: got=%v raw=%s", got, tc.raw)
		}
	}
	nameRule := map[string]any{"match": map[string]any{"op": "==", "left": map[string]any{"meta": map[string]any{"key": "oifname"}}, "right": "scqaedge0"}, "comment": "sctunqa0"}
	before, _ := json.Marshal(nameRule)
	if err := nativeNFTPinInterfaceMatches(nameRule, indices); err != nil {
		t.Fatal(err)
	}
	after, _ := json.Marshal(nameRule)
	if !bytes.Equal(before, after) {
		t.Fatal("name-based semantics or arbitrary strings were rewritten")
	}
	for _, value := range []string{"unknown0", "+22", "-1", "022", "22 ", "22.0", "1e1", "4294967296"} {
		if _, err := nativeNFTInterfaceValue(value, indices); ErrorCode(err) != "trial_resource_conflict" {
			t.Fatalf("unresolved/noncanonical interface %q accepted", value)
		}
	}
	delete(indices, r.TunnelInterface)
	value, err := nativeNFTInterfaceValue("22", indices)
	if err != nil || value != json.Number("22") {
		t.Fatal("deleted-index decimal fallback was not preserved exactly")
	}
	indices["22"] = 33
	if _, err := nativeNFTInterfaceValue("22", indices); ErrorCode(err) != "trial_resource_conflict" {
		t.Fatal("numeric interface name confused with a different missing index")
	}
}

func TestSmartTUNNativeNFTCanonicalMarkKeepsUnrelatedBits(t *testing.T) {
	r := nativeTrialExample(true)
	checked := 0
	for _, object := range nativeNFTObjects(r) {
		rule, ok := object["rule"].(map[string]any)
		if !ok {
			continue
		}
		for _, expression := range rule["expr"].([]any) {
			mangle, ok := expression.(map[string]any)["mangle"].(map[string]any)
			if !ok {
				continue
			}
			parts := mangle["value"].(map[string]any)["|"].([]any)
			and64, aok := nativeGuardNumber(parts[0].(map[string]any)["&"].([]any)[1])
			or64, ook := nativeGuardNumber(parts[1])
			if !aok || !ook || and64 != 0xff53ffff || or64 != 0x00530000 {
				t.Fatal("compiled mark does not use the proven stable native shape")
			}
			for field := uint32(0); field < 256; field++ {
				for _, other := range []uint32{0, 1, 0x80000000, 0xff00ffff, 0x81001234} {
					before := other | field<<16
					after := (before & uint32(and64)) | uint32(or64)
					if after&nativeTUNMarkMask != nativeTUNCaptureMark || after & ^nativeTUNMarkMask != before & ^nativeTUNMarkMask {
						t.Fatal("capture overwrote an unrelated mark bit or retained old reserved bits")
					}
				}
			}
			checked++
		}
	}
	if checked != 2 {
		t.Fatal("both family capture operations must preserve unrelated mark bits")
	}
}
